package main

import("encoding/json";"net/http";"strconv";"strings";"github.com/jackc/pgx/v5/pgxpool")
type transferDocumentLine struct{ProductID string `json:"productId"`;BatchID string `json:"batchId"`;Quantity float64 `json:"quantity"`}
type transferDocumentInput struct{FromBranchID string `json:"fromBranchId"`;ToBranchID string `json:"toBranchId"`;Reference string `json:"reference"`;Notes string `json:"notes"`;RequestID string `json:"requestId"`;Lines []transferDocumentLine `json:"lines"`}
func createTransferDocument(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x transferDocumentInput;if json.NewDecoder(r.Body).Decode(&x)!=nil||x.FromBranchID==""||x.ToBranchID==""||x.FromBranchID==x.ToBranchID||x.RequestID==""||len(x.Lines)==0{http.Error(w,"source, destination, request ID and lines are required",400);return};c:=claimsFrom(r);tx,e:=db.Begin(r.Context());if e!=nil{http.Error(w,e.Error(),500);return};defer tx.Rollback(r.Context());var id,no string;e=tx.QueryRow(r.Context(),`INSERT INTO stock_transfer_documents(tenant_id,document_no,from_branch_id,to_branch_id,reference,notes,created_by,client_request_id)VALUES($1,'ST-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),$2,$3,NULLIF($4,''),NULLIF($5,''),NULLIF($6,'')::uuid,$7)RETURNING id,document_no`,c.Tenant,x.FromBranchID,x.ToBranchID,strings.TrimSpace(x.Reference),strings.TrimSpace(x.Notes),c.Sub,x.RequestID).Scan(&id,&no);if e!=nil{http.Error(w,"transfer request duplicated or branches invalid",409);return};for lineIndex,line:=range x.Lines{if line.ProductID==""||line.Quantity<=0{http.Error(w,"every transfer line requires product and positive quantity",400);return};tag,err:=tx.Exec(r.Context(),`INSERT INTO stock_transfers(tenant_id,document_id,from_branch_id,to_branch_id,product_id,batch_id,quantity,status,reference,document_no,notes,transferred_by,client_request_id) SELECT $1,$2,$3,$4,p.id,NULLIF($6,'')::uuid,$7,'draft',NULLIF($8,''),$9,NULLIF($10,''),NULLIF($11,'')::uuid,$12 FROM products p WHERE p.id=$5 AND p.tenant_id=$1 AND p.is_active AND (NULLIF($6,'')::uuid IS NULL OR EXISTS(SELECT 1 FROM stock_batches b WHERE b.id=NULLIF($6,'')::uuid AND b.product_id=p.id AND b.branch_id=$3))`,c.Tenant,id,x.FromBranchID,x.ToBranchID,line.ProductID,line.BatchID,line.Quantity,x.Reference,no,x.Notes,c.Sub,x.RequestID+"-"+strconv.Itoa(lineIndex));if err!=nil||tag.RowsAffected()!=1{http.Error(w,"invalid product or batch in transfer",409);return}};if e=tx.Commit(r.Context());e!=nil{http.Error(w,e.Error(),500);return};auditUserAction(r,db,"STOCK_TRANSFER_DOCUMENT_CREATED",id,map[string]any{"documentNo":no,"lines":len(x.Lines)});w.WriteHeader(201);json.NewEncoder(w).Encode(map[string]any{"id":id,"documentNo":no,"status":"draft"})}}
func listTransferDocuments(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){rows,e:=db.Query(r.Context(),`SELECT d.id,d.document_no,fb.name,tb.name,d.status,COALESCE(d.reference,''),COALESCE(d.notes,''),d.created_at,COALESCE(string_agg(p.name||CASE WHEN b.batch_no IS NULL THEN '' ELSE ' ['||b.batch_no||']' END,', ' ORDER BY t.created_at),''),COALESCE(sum(t.quantity),0),count(t.id) FROM stock_transfer_documents d JOIN branches fb ON fb.id=d.from_branch_id JOIN branches tb ON tb.id=d.to_branch_id LEFT JOIN stock_transfers t ON t.document_id=d.id LEFT JOIN products p ON p.id=t.product_id LEFT JOIN stock_batches b ON b.id=t.batch_id WHERE d.tenant_id=$1 GROUP BY d.id,fb.name,tb.name ORDER BY d.created_at DESC`,claimsFrom(r).Tenant);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,no,from,to,status,ref,notes,products string;var at any;var qty float64;var count int;if rows.Scan(&id,&no,&from,&to,&status,&ref,&notes,&at,&products,&qty,&count)==nil{out=append(out,map[string]any{"id":id,"documentNo":no,"from":from,"to":to,"status":status,"reference":ref,"notes":notes,"createdAt":at,"product":products,"quantity":qty,"lineCount":count})}};json.NewEncoder(w).Encode(out)}}
func transferDocumentAction(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){id,action:=r.PathValue("id"),r.PathValue("action");if action!="approve"&&action!="dispatch"&&action!="receive"&&action!="cancel"{http.Error(w,"invalid action",404);return};var x struct{Reason string `json:"reason"`};json.NewDecoder(r.Body).Decode(&x);if action=="cancel"&&strings.TrimSpace(x.Reason)==""{http.Error(w,"cancellation reason required",400);return};c:=claimsFrom(r);tx,e:=db.Begin(r.Context());if e!=nil{http.Error(w,e.Error(),500);return};defer tx.Rollback(r.Context());var from,to,status string;e=tx.QueryRow(r.Context(),`SELECT from_branch_id,to_branch_id,status FROM stock_transfer_documents WHERE id=$1 AND tenant_id=$2 FOR UPDATE`,id,c.Tenant).Scan(&from,&to,&status);if e!=nil{http.Error(w,"transfer document not found",404);return};expected,next:=map[string]string{"approve":"draft","dispatch":"approved","receive":"dispatched","cancel":status}[action],map[string]string{"approve":"approved","dispatch":"dispatched","receive":"received","cancel":"cancelled"}[action];if status!=expected||(action=="cancel"&&status!="draft"&&status!="approved"){http.Error(w,"action is not allowed in current status",409);return};if action=="dispatch"||action=="receive"{rows,err:=tx.Query(r.Context(),`SELECT t.id,t.product_id,COALESCE(t.batch_id::text,''),t.quantity,p.stock_quantity FROM stock_transfers t JOIN products p ON p.id=t.product_id WHERE t.document_id=$1 ORDER BY t.created_at FOR UPDATE OF t,p`,id);if err!=nil{http.Error(w,err.Error(),500);return};type line struct{id,product,batch string;qty,balance float64};lines:=[]line{};for rows.Next(){var l line;if rows.Scan(&l.id,&l.product,&l.batch,&l.qty,&l.balance)==nil{lines=append(lines,l)}};rows.Close();for _,l:=range lines{if action=="dispatch"{tag,err:=tx.Exec(r.Context(),`UPDATE branch_stock SET quantity=quantity-$3 WHERE product_id=$1 AND branch_id=$2 AND quantity>=$3`,l.product,from,l.qty);if err!=nil||tag.RowsAffected()!=1{http.Error(w,"insufficient source stock",409);return};if l.batch!=""{tag,err=tx.Exec(r.Context(),`UPDATE stock_batches SET available_qty=available_qty-$2 WHERE id=$1 AND branch_id=$3 AND available_qty>=$2`,l.batch,l.qty,from);if err!=nil||tag.RowsAffected()!=1{http.Error(w,"insufficient batch stock",409);return}};_,e=tx.Exec(r.Context(),`INSERT INTO stock_movements(product_id,kind,quantity,tenant_id,branch_id,reference_type,reference_id,balance_after,notes,created_by)VALUES($1,'transfer_out',$2,$3,$4,'stock_transfer_document',$5,$6,$7,$8)`,l.product,-l.qty,c.Tenant,from,id,l.balance,"Dispatched to "+to,c.Sub)}else{_,e=tx.Exec(r.Context(),`INSERT INTO branch_stock(product_id,branch_id,quantity)VALUES($1,$2,$3)ON CONFLICT(product_id,branch_id)DO UPDATE SET quantity=branch_stock.quantity+EXCLUDED.quantity`,l.product,to,l.qty);if e==nil&&l.batch!=""{_,e=tx.Exec(r.Context(),`INSERT INTO stock_batches(product_id,branch_id,batch_no,manufactured_date,expiry_date,available_qty,unit_cost,status,notes)SELECT product_id,$2,batch_no,manufactured_date,expiry_date,$3,unit_cost,'available','Transfer '||$4 FROM stock_batches WHERE id=$1`,l.batch,to,l.qty,id)};if e==nil{_,e=tx.Exec(r.Context(),`INSERT INTO stock_movements(product_id,kind,quantity,tenant_id,branch_id,reference_type,reference_id,balance_after,notes,created_by)VALUES($1,'transfer_in',$2,$3,$4,'stock_transfer_document',$5,$6,$7,$8)`,l.product,l.qty,c.Tenant,to,id,l.balance,"Received from "+from,c.Sub)}};if e!=nil{http.Error(w,e.Error(),500);return}}};_,e=tx.Exec(r.Context(),`UPDATE stock_transfer_documents SET status=$2,approved_by=CASE WHEN $2='approved' THEN $3 ELSE approved_by END,approved_at=CASE WHEN $2='approved' THEN now() ELSE approved_at END,dispatched_by=CASE WHEN $2='dispatched' THEN $3 ELSE dispatched_by END,dispatched_at=CASE WHEN $2='dispatched' THEN now() ELSE dispatched_at END,received_by=CASE WHEN $2='received' THEN $3 ELSE received_by END,received_at=CASE WHEN $2='received' THEN now() ELSE received_at END,cancelled_by=CASE WHEN $2='cancelled' THEN $3 ELSE cancelled_by END,cancelled_at=CASE WHEN $2='cancelled' THEN now() ELSE cancelled_at END,cancellation_reason=CASE WHEN $2='cancelled' THEN $4 ELSE cancellation_reason END,updated_at=now() WHERE id=$1`,id,next,c.Sub,strings.TrimSpace(x.Reason));if e==nil{_,e=tx.Exec(r.Context(),`UPDATE stock_transfers SET status=$2 WHERE document_id=$1`,id,next)};if e!=nil||tx.Commit(r.Context())!=nil{http.Error(w,"transfer update failed",409);return};auditUserAction(r,db,"STOCK_TRANSFER_DOCUMENT_"+strings.ToUpper(next),id,x);w.WriteHeader(204)}}
